<?php namespace App\Filament\Resources\PageResource\Pages; use App\Filament\Pages\EditAuditedRecord; use App\Filament\Resources\PageResource; use App\Services\{ContentSanitizer,EditorialMediaAttachments}; class EditPage extends EditAuditedRecord {protected static string $resource=PageResource::class; protected function mutateFormDataBeforeFill(array $data):array{$data['content_html']=app(EditorialMediaAttachments::class)->forEditor($data['content_html']??'');return $data;} protected function mutateFormDataBeforeSave(array $data):array{$data['content_html']=app(ContentSanitizer::class)->sanitize($data['content_html']??'')['html'];if(($data['status']??null)==='published'&&!($data['published_at']??null))$data['published_at']=now();return $data;}}
